//! 🎯️ Stable IFC2x3 instance selection and typed inspection over its own snapshot provider.
use semio_s_artifact_stdio_ifc_2x3_base_model::standards::v2x3::subsets::base::schema::snapshot::Ifc2x3Snapshot;
use semio_s_artifact_stdio_contract::{editing::{self,SnapshotEditEvent,SnapshotDetailsProvider,SnapshotDetailPathSegment as P,SnapshotDetailValue,SnapshotDetailPresentation,SnapshotDetailItemCapabilities,SnapshotDetailVariant},part21::Part21Value};
