pub const DOMAIN:&str="ifc2x3-entities";
pub const GRANULARITY:&str="entity";
pub const BODY_KEY:&str="s.stdio.ifc2x3.inspector";
pub fn window_definition(editable:bool)->WindowKindDefinition{let mut window=editing::snapshot_details_window_definition();window.id=BODY_KEY.into();window.body_key=BODY_KEY.into();window.label=LocalizedLabel::native("IFC2x3 Inspector","IFC2x3-Inspektor");window.icon_id="scan-search".into();if !editable{window.actions.clear();}window}
fn row(snapshot:&Ifc2x3Snapshot,id:u64,tick:&mut dyn FnMut()->Result<(),String>)->Result<usize,String>{for (row,instance)in snapshot.document.instances.iter().enumerate(){tick()?;if instance.id==id{return Ok(row);}}Err("selection-missing".into())}
fn pointer_identity(pointer:&str)->Option<(u64,&str)>{let pointer=pointer.strip_prefix('/')?;let (identity,suffix)=pointer.split_at(pointer.find('/').unwrap_or(pointer.len()));Some((identity::parse_ifc_entity_identity(identity)?,suffix))}
fn translate(pointer:&str,snapshot:&Ifc2x3Snapshot,tick:&mut dyn FnMut()->Result<(),String>)->Result<Option<String>,String>{if !pointer.starts_with("/ifc-"){return Ok(None);}if pointer.len()>8192{return Err("selection-path-limit".into());}let (id,suffix)=pointer_identity(pointer).ok_or("selection-invalid-path")?;Ok(Some(format!("/document/instances/{}{suffix}",row(snapshot,id,tick)?)))}
pub fn selected_edit_admission(event:&SnapshotEditEvent)->Option<bool>{let paths:Vec<&str>=match event{SnapshotEditEvent::SetValue{path,..}|SnapshotEditEvent::InsertValue{path,..}|SnapshotEditEvent::RemoveValue{path}|SnapshotEditEvent::RenameKey{path,..}=>vec![path],SnapshotEditEvent::MoveValue{from,path}=>vec![from,path],SnapshotEditEvent::ReplaceSource{..}=>return None};if !paths.iter().any(|path|path.starts_with("/ifc-")){return None;}Some(paths.iter().all(|path|!path.starts_with("/ifc-")||path.len()<=8192&&pointer_identity(path).is_some())&&protocol::OpBinary::encode_op(event).is_ok_and(|bytes|bytes.len()<=editing::SNAPSHOT_EDIT_MAXIMUM_RAW_BYTES))}
pub fn selected_edit_controlled(event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot,tick:&mut dyn FnMut()->Result<(),String>)->Result<Option<SnapshotEditEvent>,String>{let path=match event{SnapshotEditEvent::SetValue{path,..}|SnapshotEditEvent::InsertValue{path,..}|SnapshotEditEvent::RemoveValue{path}|SnapshotEditEvent::MoveValue{path,..}|SnapshotEditEvent::RenameKey{path,..}=>path,SnapshotEditEvent::ReplaceSource{..}=>return Ok(None)};let translated=translate(path,snapshot,tick)?;let from=if let SnapshotEditEvent::MoveValue{from,..}=event{translate(from,snapshot,tick)?}else{None};if translated.is_none()&&from.is_none(){return Ok(None);}let path=translated.unwrap_or_else(||path.clone());Ok(Some(match event{SnapshotEditEvent::SetValue{value,..}=>SnapshotEditEvent::SetValue{path,value:value.clone()},SnapshotEditEvent::InsertValue{value,..}=>SnapshotEditEvent::InsertValue{path,value:value.clone()},SnapshotEditEvent::RemoveValue{..}=>SnapshotEditEvent::RemoveValue{path},SnapshotEditEvent::MoveValue{from:original,..}=>SnapshotEditEvent::MoveValue{path,from:from.unwrap_or_else(||original.clone())},SnapshotEditEvent::RenameKey{key,..}=>SnapshotEditEvent::RenameKey{path,key:key.clone()},SnapshotEditEvent::ReplaceSource{..}=>unreachable!()}))}
struct Provider<'a>{details:Ifc2x3DetailsProvider<'a>,id:u64,row:usize,editable:bool}
impl Provider<'_>{fn mapped(&self,path:&[P])->Option<Vec<P>>{let [P::Key(identity),rest@..]=path else{return None};if identity!=&identity::ifc_entity_identity(self.id){return None;}let mut mapped=vec![P::Key("document".into()),P::Key("instances".into()),P::Index(self.row)];mapped.extend_from_slice(rest);Some(mapped)}}
impl SnapshotDetailsProvider for Provider<'_>{
    fn value(&self,path:&[P])->Option<SnapshotDetailValue>{if path.is_empty(){return Some(SnapshotDetailValue::Object);}if let [P::Key(identity),P::Key(field)]=path{if identity==&identity::ifc_entity_identity(self.id)&&field=="id"{return Some(SnapshotDetailValue::String(self.id.to_string()));}}self.details.value(&self.mapped(path)?)}
    fn child_count(&self,path:&[P])->usize{if path.is_empty(){return 1;}self.mapped(path).map_or(0,|path|self.details.child_count(&path))}
    fn object_key(&self,path:&[P],index:usize)->Option<String>{if path.is_empty(){return (index==0).then(||identity::ifc_entity_identity(self.id));}self.details.object_key(&self.mapped(path)?,index)}
    fn presentation(&self,path:&[P],locale:Locale)->Option<SnapshotDetailPresentation>{if path.len()==1{return Some(SnapshotDetailPresentation{label:format!("IFC2x3 #{}",self.id),description:Some(match locale{Locale::En=>"Typed attributes from the IFC2x3 TC1 catalog",Locale::De=>"Typisierte Attribute aus dem IFC2x3-TC1-Katalog"}.into())});}self.details.presentation(&self.mapped(path)?,locale)}
    fn item_capabilities(&self,path:&[P])->SnapshotDetailItemCapabilities{if !self.editable{return SnapshotDetailItemCapabilities{edit:false,rename:false,remove:false,reorder:false};}self.mapped(path).map_or(SnapshotDetailItemCapabilities{edit:false,rename:false,remove:false,reorder:false},|path|self.details.item_capabilities(&path))}
    fn enum_values(&self,path:&[P])->Vec<DslValue>{self.mapped(path).map_or_else(Vec::new,|path|self.details.enum_values(&path))}
    fn allows_untyped_creation(&self,_path:&[P])->bool{false}
    fn allows_collection_insert(&self,path:&[P])->bool{self.editable&&self.mapped(path).is_some_and(|path|self.details.allows_collection_insert(&path))}
    fn creation_template(&self,path:&[P],item:bool)->Option<DslValue>{if !self.editable{return None;}self.details.creation_template(&self.mapped(path)?,item)}
    fn variants(&self,path:&[P],locale:Locale)->Vec<SnapshotDetailVariant>{if !self.editable{return Vec::new();}self.mapped(path).map_or_else(Vec::new,|path|self.details.variants(&path,locale))}
    fn variant_count(&self,path:&[P],locale:Locale)->usize{if !self.editable{return 0;}self.mapped(path).map_or(0,|path|self.details.variant_count(&path,locale))}
    fn variant(&self,path:&[P],locale:Locale,index:usize)->Option<SnapshotDetailVariant>{if !self.editable{return None;}self.details.variant(&self.mapped(path)?,locale,index)}
}
fn ui_error(code:&'static str)->semio_framework_plugin::PluginAssemblyError{semio_framework_plugin::PluginAssemblyError::new(code,"IFC2x3 inspector admission failed")}
fn message(text:&str)->UiAssemblyResult<BuiltNode>{ui::text(ui::Label(UiText::clipped(text))).try_build().map_err(|_|ui_error("ifc2x3.inspector.message"))}
fn navigation(id:u64,controller:&str,locale:Locale)->UiAssemblyResult<BuiltNode>{let targets=semio_framework_pack_json::to_string(&semio_framework_pack_json::json!([{"granularity":GRANULARITY,"id":identity::ifc_entity_identity(id)}]));let mut args=UiMapBuilder::try_new().ok_or_else(||ui_error("ifc2x3.inspector.args"))?;for (key,value)in [("domainId",DOMAIN),("targets",targets.as_str()),("merge","replace"),("method","pick")]{args.try_insert(key.to_string(),UiValue::Text(UiText::clipped(value))).map_err(|_|ui_error("ifc2x3.inspector.arg"))?;}let label=match locale{Locale::En=>format!("Open #{id}"),Locale::De=>format!("#{id} öffnen")};ui::button(ui::Label(UiText::clipped(&label))).try_id(format!("ifc2x3-reference-{id}")).map_err(|_|ui_error("ifc2x3.inspector.link-id"))?.try_on_with(ui::Trigger::Activate,ActionId::try_v1(controller,semio_framework_plugin::INTERACTION_SELECT_ACTION_ID).ok_or_else(||ui_error("ifc2x3.inspector.link-action"))?,UiValue::Map(args.finish())).map_err(|_|ui_error("ifc2x3.inspector.link-binding"))?.try_build().map_err(|_|ui_error("ifc2x3.inspector.link"))}
fn references(value:&Part21Value,ids:&mut std::collections::BTreeSet<u64>,depth:usize,cx:&mut semio_framework_job::StepContext<'_>)->Result<(),String>{if cx.is_cancelled(){return Err("cancelled".into());}if cx.should_yield()||depth>128{return Err("limited".into());}cx.consume_fuel(1);match value{Part21Value::Ref(id)=>{ids.insert(*id);if ids.len()>256{return Err("limited".into());}},Part21Value::List(items)|Part21Value::Typed{items,..}=>for value in items{references(value,ids,depth+1,cx)?;},_=>{}}Ok(())}
pub fn render(doc:&semio_framework_plugin::ArtifactView<'_,Ifc2x3Snapshot>,interaction:&InteractionView<'_>,view:&semio_framework_plugin::ViewModel,controller:&str,editable:bool,cx:&mut semio_framework_job::StepContext<'_>)->UiAssemblyResult<BuiltNode>{let _=cx.set_stage("ifc2x3-inspector");let Some(id)=interaction.selection(DOMAIN).ids.first().and_then(|id|identity::parse_ifc_entity_identity(id))else{return message(match view.locale{Locale::En=>"Select an IFC2x3 product to inspect its attributes",Locale::De=>"IFC2x3-Produkt auswählen, um Attribute zu prüfen"})};let row=row(doc.snapshot,id,&mut ||{if cx.is_cancelled(){return Err("cancelled".into());}if cx.should_yield(){return Err("limited".into());}cx.consume_fuel(1);Ok(())});let row=match row{Ok(row)=>row,Err(reason)=>return message(match(view.locale,reason.as_str()){(Locale::En,"cancelled")=>"Inspection cancelled",(Locale::De,"cancelled")=>"Inspektion abgebrochen",(Locale::En,"limited")=>"Inspection reached its request limit",(Locale::De,"limited")=>"Inspektion hat ihr Anforderungslimit erreicht",(Locale::En,_)=>"The selected instance no longer exists",(Locale::De,_)=>"Die ausgewählte Instanz existiert nicht mehr"})};let windows=TreeWindows::for_body(view,BODY_KEY);let revision=semio_s_artifact_stdio_contract::window_kit_artifact_publication_revision(doc)?;let details=editing::render_snapshot_details_provider_revisioned(&Provider{details:Ifc2x3DetailsProvider::new(doc.snapshot),id,row,editable},revision,view.locale,controller,&windows)?;let mut children=vec![details];let mut targets=std::collections::BTreeSet::new();let mut navigation_limited=false;for (_,args)in &doc.snapshot.document.instances[row].entities{for value in args{if references(value,&mut targets,0,cx).is_err(){navigation_limited=true;break;}}if navigation_limited{break;}}if navigation_limited{children.push(message(match(view.locale,cx.is_cancelled()){(Locale::En,true)=>"Reference navigation cancelled",(Locale::De,true)=>"Referenznavigation abgebrochen",(Locale::En,false)=>"Reference navigation reached its request limit",(Locale::De,false)=>"Referenznavigation hat ihr Anforderungslimit erreicht"})?);}else{let mut resolved=Vec::new();for instance in &doc.snapshot.document.instances{if cx.is_cancelled()||cx.should_yield(){navigation_limited=true;break;}cx.consume_fuel(1);if targets.remove(&instance.id){resolved.push(instance.id);}}if navigation_limited{children.push(message(match(view.locale,cx.is_cancelled()){(Locale::En,true)=>"Reference navigation cancelled",(Locale::De,true)=>"Referenznavigation abgebrochen",(Locale::En,false)=>"Reference navigation reached its request limit",(Locale::De,false)=>"Referenznavigation hat ihr Anforderungslimit erreicht"})?);}else{for id in resolved{children.push(navigation(id,controller,view.locale)?);}for id in targets{children.push(message(&match view.locale{Locale::En=>format!("Missing reference #{id}"),Locale::De=>format!("Fehlende Referenz #{id}")})?);}}}ui::column().try_id("ifc2x3-selected-inspector").map_err(|_|ui_error("ifc2x3.inspector.id"))?.try_children(children).map_err(|_|ui_error("ifc2x3.inspector.children"))?.try_build().map_err(|_|ui_error("ifc2x3.inspector.root"))}
pub fn layout(main:&str,editable:bool)->semio_framework_plugin::WindowLayout{let mut layout=editing::snapshot_details_split_layout(main,"Main");if let semio_framework_plugin::WindowLayoutRoot::Axis(axis)=&mut layout.root{if let Some(semio_framework_plugin::WindowLayoutChild::Stack(stack))=axis.children.last_mut(){if !editable{stack.children.clear();}stack.active_window_kind_id=Some(BODY_KEY.into());stack.children.insert(0,semio_framework_plugin::WindowLayoutWindowNode{kind:"window".into(),window_kind_id:BODY_KEY.into(),title:None,instance_id:None,template_id:None,corner:None});}}layout}
pub fn topology(snapshot:&Ifc2x3Snapshot)->protocol::InteractionTopology{let ordered=snapshot.document.instances.iter().map(|instance|protocol::TopologyNode{id:identity::ifc_entity_identity(instance.id),granularity:GRANULARITY.into(),parent:None}).collect();let mut domains=std::collections::BTreeMap::new();domains.insert(DOMAIN.into(),protocol::DomainTopology{ordered});protocol::InteractionTopology{domains}}
pub fn install_interaction(definition:&mut semio_framework_plugin::AppDefinition){definition.interactions.push(semio_framework_plugin::InteractionDefinition{id:DOMAIN.into(),label:LocalizedLabel::native("IFC2x3 Instances","IFC2x3-Instanzen"),granularities:vec![semio_framework_plugin::GranularityDefinition{id:GRANULARITY.into(),label:LocalizedLabel::native("Instance","Instanz"),icon_id:"box".into()}],hierarchy:semio_framework_plugin::HierarchyProvider::Topology,hover:semio_framework_plugin::HoverSpec::default(),selection:semio_framework_plugin::SelectionSpec{modes:vec![semio_framework_plugin::SelectionMode::Multiple,semio_framework_plugin::SelectionMode::Single],methods:vec![semio_framework_plugin::SelectionMethod::Pick],merges:vec![semio_framework_plugin::MergeMode::Replace,semio_framework_plugin::MergeMode::Invertive],transitive:false,broadcast:true}});for window in &mut definition.window_kinds{if window.id==BODY_KEY||window.id==semio_framework_plugin::MeshWindowKit::KIND_ID{window.interactions=vec![semio_framework_plugin::InteractionRef::new(DOMAIN)];}}}

