pub fn edit_is_admitted(event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot)->bool{selected_edit_admission(event).unwrap_or_else(||crate::standards::v2x3::subsets::base::io::details::details_edit_is_admitted(event,snapshot))}
pub fn edit_special(event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot)->Result<Option<Vec<semio_s_artifact_stdio_ifc_2x3_base_mutations::standards::v2x3::subsets::base::schema::mutations::Ifc2x3Mutation>>,semio_framework_plugin::Fault>{let selected=selected_edit_controlled(event,snapshot,&mut ||Ok(())).map_err(semio_framework_plugin::Fault::from)?;crate::standards::v2x3::subsets::base::io::details::details_edit_special(selected.as_ref().unwrap_or(event),snapshot)}
pub fn edit_in_context(event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot,cx:&mut semio_framework_job::StepContext<'_>)->Result<Vec<semio_s_artifact_stdio_ifc_2x3_base_mutations::standards::v2x3::subsets::base::schema::mutations::Ifc2x3Mutation>,semio_framework_plugin::Fault>{use semio_s_artifact_stdio_ifc_2x3_base_mutations::standards::v2x3::subsets::base::schema::mutations::Ifc2x3Mutation;use semio_framework_plugin::Fault;fn tick(cx:&mut semio_framework_job::StepContext<'_>)->Result<(),String>{if cx.is_cancelled(){return Err("details-cancelled".into());}if cx.should_yield(){return Err("details-limited".into());}cx.consume_fuel(1);Ok(())}let _=cx.set_stage("ifc2x3-details-edit");let selected=selected_edit_controlled(event,snapshot,&mut ||tick(cx)).map_err(Fault::from)?;let event=selected.as_ref().unwrap_or(event);let mutations=crate::standards::v2x3::subsets::base::io::details::details_edit_special_controlled(event,snapshot,&mut ||tick(cx))?.unwrap_or_default();if cx.is_cancelled(){return Err(Fault::from("details-cancelled"));}if cx.should_yield(){return Err(Fault::from("details-limited"));}let rows=mutations.iter().try_fold(0usize,|rows,mutation|rows.checked_add(1).and_then(|rows|rows.checked_add(<Ifc2x3Mutation as protocol::Mutation<Ifc2x3Snapshot>>::inverse_rows(mutation)))).ok_or_else(||Fault::from("IFC2x3 publication row count overflow"))?;if rows>0&&!edit_capacity().admits(rows){return Err(Fault::from("IFC2x3 publication exceeds declared row capacity"));}editing::check_publication_limits(snapshot,&mutations)?;if cx.is_cancelled(){return Err(Fault::from("details-cancelled"));}if cx.should_yield(){return Err(Fault::from("details-limited"));}Ok(mutations)}
